int main(){using namespace auto_animation::animation;using namespace auto_animation::rigging;using namespace auto_animation::motion;int f=0;auto e=[&](bool v,const char*m){if(!v){std::cerr<<"FAIL: "<<m<<'\n';++f;}};Skeleton s;auto r=s.add_bone("Root",-1);auto b=s.add_bone("Body",r);auto wl=s.add_bone("Wing_L",b);auto wr=s.add_bone("Wing_R",b);auto ll=s.add_bone("Leg_L",b);auto lr=s.add_bone("Leg_R",b);auto c=generate_fly_idle(s,{r,b,wl,wr,ll,lr});e(c.name=="FlyIdle","stable name");e(c.looping&&!c.root_motion,"stationary loop");e(c.tracks.size()==6,"all controls tracked");e(c.tracks[0].translation.keys.size()==5,"five loop keys");e(std::abs(c.tracks[0].translation.keys.front().value.z-c.tracks[0].translation.keys.back().value.z)<1e-5f,"root loop closes");e(c.tracks[4].translation.keys.front().value.z!=c.tracks[5].translation.keys.front().value.z,"legs asymmetric");e(validate(c).valid(),"generated clip validates");return f;}
